// Checkout conversion fix: ensure offer acceptance triggers payment event
const { logEvent } = require('./eventLogger');

module.exports = function fixCheckoutConversion(req, res, next) {
  const originalJson = res.json.bind(res);
  res.json = function (body) {
    if (req.path === '/api/checkout/complete' && res.statusCode === 200) {
      logEvent('paidEvent', { userId: req.user?.id, amount: body?.amount });
    }
    return originalJson(body);
  };
  next();
};
